SELECT l_returnflag, l_linestatus, sum(l_quantity) AS sq, sum(l_extendedprice) AS se, sum(l_extendedprice * (1 - l_discount)) AS sd, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) AS sc, avg(l_quantity) AS aq, avg(l_extendedprice) AS ae, avg(l_discount) AS ad, count(*) AS c FROM lineitem WHERE l_shipdate <= DATE '1998-12-01' GROUP BY l_returnflag, l_linestatus ORDER BY l_returnflag, l_linestatus
